export function createNodeData(
  kind: WorkflowNodeKind,
  overrides?: Partial<WorkflowNodeData>,
): WorkflowNodeData {
  const definition = nodeDefinitions[kind];

  return {
    ...definition,
    notes:
      overrides?.notes ??
      "Keep this node opinionated: compact defaults, clear output, low-friction edits.",
    config: {
      ...defaultConfig[kind],
      ...overrides?.config,
    },
    ...overrides,
    kind,
  };
}

export function createWorkflowNode(
  kind: WorkflowNodeKind,
  position: XYPosition,
  overrides?: Partial<WorkflowNodeData>,
): WorkflowNode {
  return {
    id: createId(kind),
    type: "blueprint",
    position,
    data: createNodeData(kind, overrides),
  };
}

export function instantiateTemplate(templateId: string, position: XYPosition) {
  const template = TEMPLATE_LIBRARY.find((item) => item.id === templateId);

  if (!template) {
    return { nodes: [], edges: [] };
  }

  const idMap = new Map<string, string>();

  const nodes = template.nodes.map((node) => {
    const nextId = createId(node.kind);
    idMap.set(node.id, nextId);

    return {
      id: nextId,
      type: "blueprint",
      position: {
        x: position.x + node.offset.x,
        y: position.y + node.offset.y,
      },
      data: createNodeData(node.kind, node.overrides),
    } satisfies WorkflowNode;
  });

  const edges = template.edges.map((edge) => ({
    id: createId("edge"),
    source: idMap.get(edge.source) ?? edge.source,
    target: idMap.get(edge.target) ?? edge.target,
    label: edge.label,
    animated: edge.animated ?? false,
    type: "smoothstep",
    markerEnd: { type: MarkerType.ArrowClosed },
  })) satisfies WorkflowEdge[];

  return { nodes, edges };
}

export function createDefaultFlow(name = "Blueprint Workspace"): WorkflowDocument {
  const { nodes, edges } = instantiateTemplate("lead-intake", { x: 80, y: 80 });

  return {
    name,
    updatedAt: new Date().toISOString(),
    saveMode: "seed",
    nodes,
    edges,
    viewport: defaultViewport,
  };
}

export function getTemplate(templateId: string) {
  return TEMPLATE_LIBRARY.find((item) => item.id === templateId) ?? null;
}

export function cloneDocument(document: WorkflowDocument) {
  return structuredClone(document);
}
